actions.script:
const L = (text) => ec.l10n.localize(text)
if (!['skip', 'update'].includes(existingPolicy)) { ec.message.addValidationError(null, 'existingPolicy', null, L('Choose what to do with rows already imported'), null); return }
ec.service.sync().name('ironstone.projects.WorkItemImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'options',
    options: {createMissing: createMissing === 'Y', existingPolicy: existingPolicy}}}).call()

hasDraft = !!draftOut.found
const saved = (draftOut.draft || {}).options || {}
options = {importId: importId, createMissing: saved.createMissing === false ? 'N' : 'Y', existingPolicy: saved.existingPolicy || 'skip'}
